import {encodeSyncBytes} from '../sync/archiveTransfer';
import {useEffect} from 'react';
import type {ProjectData} from '../domain/types';
import type {ScenarioStore} from '../storage';
import {useAuthorScope,useScenarioStore} from './StoreContext';
import {useSyncClient} from './SyncContext';
import {authorField,useAuthorField,useAuthorInput,flushAuthorDraft,acknowledgeAuthorDraft,AuthorDraftNotice} from './authorOperation';
import {AccountScopedSyncStore} from '../sync/adapter';
import {SyncOutbox,type SyncReport} from '../sync/outbox';
import type {ConfirmedSyncBase,PreservedNativeConflict} from '../sync/nativeBridge';
import type {ConflictResolution} from '../sync/merge';
import {closureAttachmentMetadata,validateAsset} from '../storage/archive';
import {sha256} from '../storage/json';
import {ListPager,useListWindow} from './ListWindow';
type Plan=Awaited<ReturnType<ScenarioStore['previewSyncResolution']>>;
export function SyncPanel({project,onUpdated}:{project:ProjectData;onUpdated:(p:ProjectData)=>void}){
 const store=useScenarioStore(),client=useSyncClient(),scope=useAuthorScope(`sync:${project.projectId}`),[controller,setController]=useAuthorField<AbortController|null>(scope,'controller',null),[busy,setBusy]=useAuthorField(scope,'busy',false),[error,setError]=useAuthorField(scope,'error',''),[notice,setNotice]=useAuthorField(scope,'notice',''),[base,setBase]=useAuthorField<ConfirmedSyncBase|undefined>(scope,'base',undefined),[conflicts,setConflicts]=useAuthorField<PreservedNativeConflict[]>(scope,'conflicts',[]),[report,setReport]=useAuthorField<SyncReport|null>(scope,'report',null),[plan,setPlan]=useAuthorField<Plan|null>(scope,'plan',null),[choices,setChoices]=useAuthorInput<Record<string,ConflictResolution>>(scope,'choices',{},project.projectId,project.revision),[combined,setCombined]=useAuthorInput<Record<string,string>>(scope,'combined',{},project.projectId,project.revision);
 const view=useListWindow({items:conflicts.map(c=>({...c,id:c.operationId})),scope:`${scope}:conflicts`,size:10});
 useEffect(()=>{if(!store.accountId)return;let live=true;void Promise.all([store.getConfirmedSyncBase(project.projectId),store.listSyncConflictAlternatives(project.projectId)]).then(([b,c])=>{if(live){setBase(b);setConflicts(c);}}).catch(cause=>{if(live)setError((cause as Error).message);});return()=>{live=false;};},[project.revision,scope]);
 async function refresh(){setBase(await store.getConfirmedSyncBase(project.projectId));setConflicts(await store.listSyncConflictAlternatives(project.projectId));const current=await store.getProjectForEditing(project.projectId);if(current)onUpdated(current);}
 async function run(task:()=>Promise<void>){if(authorField<boolean>(scope,'busy'))return;const abort=new AbortController();setController(abort);setBusy(true);setError('');setNotice('');try{if(!store.accountId||!client)throw Error('DEDICATED_CONNECTION_REQUIRED');await task();}catch(cause){setError((cause as Error).message);}finally{setBusy(false);setController(null);}}
 async function bootstrap(){const source=structuredClone(project),expected=client!.getSession(),outboxIds=(await store.listOutbox(source.projectId)).filter(o=>BigInt(o.localRevision)<=BigInt(source.revision)).map(o=>o.operationId),worlds=await store.listWorldSnapshots();const result=await client!.request<{serverRevision:string;documents:ConfirmedSyncBase['documents'];contentHash:string}>('bootstrap',{project:source,worlds},expected,authorField<AbortController>(scope,'controller')?.signal);await store.bindBootstrapBase(source,{...result,outboxIds});await refresh();setNotice('新しいサーバー正本と確定共通元を保存しました。通信中の後発編集は保存待ちへ保持します。');}
 async function uploadBytes(){const expected=client!.getSession(),source=await store.getProject(project.projectId);if(!source)return;const metadata=closureAttachmentMetadata(source,await store.listWorldSnapshots());for(const [index,m]of metadata.entries()){setNotice(`素材bytesを確認・送信 ${index+1}/${metadata.length}`);if(await store.getAssetSyncAck(source.projectId,m.contentHash))continue;const bytes=await store.getAsset(m.contentHash);if(!bytes)throw Error('ASSET_BYTES_REQUIRED');let raw='';for(let start=0;start<bytes.length;start+=65536){if(authorField<AbortController>(scope,'controller')?.signal.aborted)throw Error('CANCELLED');raw+=Array.from(bytes.subarray(start,start+65536),value=>String.fromCharCode(value)).join('');if(start%1048576===0)await new Promise(resolve=>setTimeout(resolve,0));}const ack=await client!.request<{contentHash:string;bytes:number}>('upload_asset',{projectId:source.projectId,contentHash:m.contentHash,base64:btoa(raw)},expected,authorField<AbortController>(scope,'controller')?.signal);await store.confirmAssetUpload(source.projectId,{...ack,mediaType:m.mediaType});}}
 async function synchronize(){const queue=new SyncOutbox(new AccountScopedSyncStore(store as ScenarioStore&{accountId:string}),client!.getSession,client);const result=await queue.flush({accountId:store.accountId!,projectId:project.projectId},{signal:authorField<AbortController>(scope,'controller')?.signal,onProgress:(done,left)=>setNotice(`確定ACK ${done}件・保存待ち ${left}件`)});setReport(result);await refresh();if(['failed','forbidden','auth-required','account-changed','not-configured'].includes(result.status))throw Error(result.errorCode??'SYNC_FAILED');if(result.status!=='conflict'&&result.errorCode!=='CANCELLED')await uploadBytes();const saved=await store.getSaveState(project.projectId);setReport({...result,remaining:result.remaining+saved.pendingAssetCount,status:saved.syncState==='conflict'?'conflict':saved.pendingCount||saved.pendingAssetCount?'pending':result.status});}
 async function pull(){const expected=client!.getSession(),result=await client!.request<{project:ProjectData;documents:ConfirmedSyncBase['documents'];serverRevision:string;contentHash:string;worlds:Record<string,ProjectData>}>('pull',{projectId:project.projectId},expected,authorField<AbortController>(scope,'controller')?.signal);
  // Every byte is fetched and checked before the native ack may refer to it.
  for(const m of closureAttachmentMetadata(result.project,result.worlds)){if(await store.getAsset(m.contentHash))continue;const bytes=await client!.downloadAsset({projectId:project.projectId,contentHash:m.contentHash},expected,authorField<AbortController>(scope,'controller')?.signal);if(await sha256(bytes)!==m.contentHash||bytes.byteLength!==m.byteSize)throw Error('ASSET_BYTES_REQUIRED');validateAsset(m.assetPath,m.mediaType,bytes);await store.putAsset(m.contentHash,bytes,m.mediaType);}
  await store.applyReceivedImage(project.projectId,result);await refresh();setNotice('確定版を取得しました。端末の未送信編集と競合の二案を保持しています。');}
 async function uploadArchive(){const expected=client!.getSession(),confirmed=await store.getConfirmedSyncBase(project.projectId),state=await store.getSaveState(project.projectId);if(!confirmed||state.pendingCount||state.pendingAssetCount||state.syncState==='conflict')throw Error('COMPLETE_SYNC_REQUIRED');const signal=authorField<AbortController>(scope,'controller')?.signal,bytes=await store.exportProject(project.projectId,{signal}),hash=await sha256(bytes);const base64=await encodeSyncBytes(bytes,signal,(done,total)=>setNotice(`完全保存bytesを準備 ${done}/${total}`));await client!.request('upload_archive',{projectId:project.projectId,serverRevision:confirmed.serverRevision,contentHash:hash,base64},expected,signal);setNotice('履歴・旧固定版・世界依存・送信証跡・素材bytesを含む完全保存をこのサーバー版に保持しました。別端末のアカウント欄から復元できます。');}
 const stale=!!plan&&plan.localRevision!==project.revision;
 return <section className="settings-card" aria-label="端末間同期と競合"><h2>端末間同期</h2><p>端末内保存とサーバー確定は別です。{base?`確定共通元 ${base.serverRevision}`:'未接続の作品です。新規登録するか、完全保存した作品を認証した領域へ明示復元してください。'}</p>{!store.accountId&&<p>アカウント欄で専用接続先を設定し、認証した領域で開いてください。端末内作品はそのまま使用できます。</p>}<div className="world-inline-actions"><button className="button secondary" disabled={busy||!store.accountId||!!base} onClick={()=>void run(bootstrap)}>この作品を専用接続先へ新規登録</button><button className="button primary" disabled={busy||!base} onClick={()=>void run(synchronize)}>保存待ちを同期</button><button className="button secondary" disabled={busy||!base||!!conflicts.length} onClick={()=>void run(pull)}>確定版を取得・後発編集を保持</button><button className="button secondary" disabled={busy||!base} onClick={()=>void run(uploadArchive)}>確定版の完全保存を接続先へ保持</button></div>{report&&<p role="status">{report.status} · ACK {report.acknowledged}件 · 待ち {report.remaining}件 · 競合 {report.conflicts}件 · 確定版 {report.confirmedRevision??'未取得'}</p>}
 {view.items.map(row=><article key={row.operationId}><h3>競合操作 {row.operationId}</h3><p>全送信対象 {row.prepared.operation.targets.length}件を拒否した元操作と、共通元・二案を保持しています。現在の参照先への影響を確認して選択してください。</p>{row.conflicts.map(c=><div key={c.targetId}><strong>{project.entities.find(e=>e.id===c.targetId)?.name??(c.targetId===project.projectId?'作品情報':'対象')} · {c.reasons.join('、')}</strong><div className="conflict-comparison"><pre>共通元{JSON.stringify(c.base?.fields,null,2)}</pre><pre>端末案{JSON.stringify(c.local.fields,null,2)}</pre><pre>サーバー案{JSON.stringify(c.server?.fields,null,2)}</pre></div><label>この対象の選択<select value={choices[c.targetId]?.strategy??''} onChange={e=>{setChoices({...choices,[c.targetId]:e.target.value==='fields'?{strategy:'fields',choices:{}}:{strategy:e.target.value as 'local'|'server'}});setPlan(null);}}><option value="" disabled>選択してください</option><option value="local">端末案（無競合の後発編集も保持）</option><option value="server">サーバー案（無競合の後発編集も保持）</option>{c.reasons.every(r=>r==='same-field')&&<option value="fields">項目ごとに選択・組合せ</option>}</select></label>{choices[c.targetId]?.strategy==='fields'&&c.fields.map(f=>{const selected=choices[c.targetId] as Extract<ConflictResolution,{strategy:'fields'}>;return <div key={f.field}><label>{f.field}<select value={typeof selected.choices[f.field]==='string'?selected.choices[f.field] as string:selected.choices[f.field]?'combined':''} onChange={e=>{const pick=e.target.value==='combined'?{value:{present:true as const,value:null}}:e.target.value as 'local'|'server';setChoices({...choices,[c.targetId]:{strategy:'fields',choices:{...selected.choices,[f.field]:pick}}});setPlan(null);}}><option value="" disabled>選択</option><option value="local">端末</option><option value="server">サーバー</option><option value="combined">入力した組合せ</option></select></label><label>組合せJSON<textarea value={combined[c.targetId+':'+f.field]??''} onChange={e=>{setCombined({...combined,[c.targetId+':'+f.field]:e.target.value});setPlan(null);}}/></label></div>;})}</div>)}<button className="button secondary" disabled={busy||row.conflicts.some(c=>!choices[c.targetId])} onClick={()=>void run(async()=>{await flushAuthorDraft(scope);const picked=Object.fromEntries(row.conflicts.map(c=>{const choice=structuredClone(choices[c.targetId]);if(choice.strategy==='fields')for(const [field,value]of Object.entries(choice.choices))if(typeof value!=='string')choice.choices[field]={value:{present:true,value:JSON.parse(combined[c.targetId+':'+field]??'null')}};return[c.targetId,choice];}));setPlan(await store.previewSyncResolution(project.projectId,row.operationId,picked));})}>共通元・現在入力・二案の影響を確認</button></article>)}<ListPager {...view} label="同期競合"/>{plan&&<div><p>確認ローカル版 {plan.localRevision} · サーバー版 {plan.serverRevision} · 保存対象 {plan.operation.targets.length}件。参照・固定版・全対象を検査しました。</p><button className="button primary" disabled={busy||stale} onClick={()=>void run(async()=>{await store.confirmSyncResolution(plan);await refresh();setPlan(null);acknowledgeAuthorDraft(scope,(await store.getProjectForEditing(project.projectId))!.revision);await synchronize();})}>確認した解決案を保存・同期</button></div>}{stale&&<p role="alert">確認後に作品が変わりました。選択を保持して再確認してください。</p>}{busy&&<p role="status">同期操作中…<button className="button secondary" onClick={()=>controller?.abort()}>中止して保存待ちを保持</button></p>}{error&&<p role="alert">{error}</p>}{notice&&<p role="status">{notice}</p>}<AuthorDraftNotice scope={scope} revision={project.revision}/></section>;
}
